cat << 'PYEOF' > /app/solve5.py
import json
import csv
import os
from collections import defaultdict
from itertools import product

# ─── Parse all data ─────────────────────────────────────────────────
with open("/app/data/instance.txt") as f:
    lines = [l.strip() for l in f if l.strip()]
num_jobs, num_machines = map(int, lines[0].split())
allowed = {}
idx = 1
for j in range(num_jobs):
    num_ops = int(lines[idx]); idx += 1
    for o in range(num_ops):
        tokens = list(map(int, lines[idx].split())); idx += 1
        num_alt = tokens[0]
        d = {}
        for a in range(num_alt):
            d[tokens[1+2*a]] = tokens[2+2*a]
        allowed[(j,o)] = d

downtime = {}
with open("/app/data/downtime.csv") as f:
    for row in csv.DictReader(f):
        m = int(row["machine"])
        downtime.setdefault(m,[]).append((int(row["start"]),int(row["end"])))
for m in downtime: downtime[m].sort()

with open("/app/data/policy.json") as f:
    policy = json.load(f)
max_mc = policy["change_budget"]["max_machine_changes"]
max_shift = policy["change_budget"]["max_total_start_shift_L1"]

with open("/app/data/baseline_solution.json") as f:
    baseline = json.load(f)
base_list = baseline["schedule"]
base_map = {(r["job"],r["op"]):r for r in base_list}

def precedence_aware_order(bl):
    bm = {(r["job"],r["op"]):r for r in bl}
    bi = {(r["job"],r["op"]):i for i,r in enumerate(bl)}
    keys = list(bm.keys())
    keys.sort(key=lambda k: (k[1], bm[k]["start"], bi[k]))
    return keys

order = precedence_aware_order(base_list)

def overlap(s,e,a,b): return s<b and a<e

def has_conflict(m, st, en, mi, dt):
    for a,b in mi.get(m,[]):
        if overlap(st,en,a,b): return True
    for a,b in dt.get(m,[]):
        if overlap(st,en,a,b): return True
    return False

def earliest_feasible_time(m, anchor, dur, mi, dt):
    t = int(anchor)
    for _ in range(200000):
        if not has_conflict(m,t,t+dur,mi,dt): return t
        t += 1
    return t

# ─── Enumerate machine assignments for all 12 operations ────────────
# Each op has 2 candidate machines, so 2^12 = 4096 combinations
# For each combination, run the greedy schedule and check feasibility.

ops_keys = list(order)
machine_choices_per_op = []
for (j,o) in ops_keys:
    machines = list(allowed[(j,o)].keys())
    machine_choices_per_op.append(machines)

print(f"Operations: {ops_keys}")
print(f"Machine choices: {machine_choices_per_op}")
total_combos = 1
for mc in machine_choices_per_op:
    total_combos *= len(mc)
print(f"Total combinations: {total_combos}")

best_ms = float('inf')
best_result = None
count = 0

for combo in product(*machine_choices_per_op):
    count += 1
    # Check machine change budget first
    mc_count = sum(1 for i,(j,o) in enumerate(ops_keys) if combo[i] != base_map[(j,o)]["machine"])
    if mc_count > max_mc:
        continue

    # Build schedule greedily with fixed machine assignments
    machine_intervals = {}
    new_schedule = {}
    shift_total = 0
    feasible = True

    for idx_op, (j,o) in enumerate(ops_keys):
        mm = combo[idx_op]
        dd = allowed[(j,o)][mm]
        base_start = base_map[(j,o)]["start"]

        if o > 0:
            anchor = max(base_start, new_schedule[(j,o-1)]["end"])
        else:
            anchor = base_start

        st = earliest_feasible_time(mm, anchor, dd, machine_intervals, downtime)
        en = st + dd
        shift_total += abs(st - base_start)

        if shift_total > max_shift:
            feasible = False
            break

        machine_intervals.setdefault(mm,[]).append((st, en))
        new_schedule[(j,o)] = {"job":j,"op":o,"machine":mm,"start":st,"end":en,"dur":dd}

    if not feasible:
        continue

    makespan = max(r["end"] for r in new_schedule.values())
    if makespan < best_ms:
        best_ms = makespan
        best_result = (dict(new_schedule), makespan, mc_count, shift_total)
        print(f"  New best: makespan={makespan}, mc={mc_count}, shift={shift_total}, combo={combo}")

print(f"\nSearched {count} valid combos out of {total_combos}")

if best_result:
    sched, ms, mc, sh = best_result
    print(f"\nBEST: makespan={ms}, mc={mc}/{max_mc}, shift={sh}/{max_shift}")

    # Details
    for (j,o) in order:
        r = sched[(j,o)]
        br = base_map[(j,o)]
        ch = "CHANGED" if r["machine"]!=br["machine"] else "same"
        print(f"  ({j},{o}): M{r['machine']} [{r['start']},{r['end']}) dur={r['dur']}  base: M{br['machine']} [{br['start']},{br['end']}) mc={ch} shift={abs(r['start']-br['start'])}")

    # Validate
    errors = 0
    for (j,o), rec in sched.items():
        if o > 0:
            prev = sched[(j,o-1)]
            if prev["end"] > rec["start"]:
                print(f"  PRECEDENCE ERROR: ({j},{o})"); errors+=1
        m = rec["machine"]
        for a,b in downtime.get(m,[]):
            if overlap(rec["start"],rec["end"],a,b):
                print(f"  DOWNTIME ERROR: ({j},{o}) M{m} [{rec['start']},{rec['end']}) vs [{a},{b})"); errors+=1
        if rec["machine"] not in allowed[(j,o)]:
            print(f"  INVALID MACHINE: ({j},{o})"); errors+=1
        if rec["dur"] != allowed[(j,o)][rec["machine"]]:
            print(f"  DURATION ERROR: ({j},{o})"); errors+=1

    m_ops = defaultdict(list)
    for (j,o), rec in sched.items():
        m_ops[rec["machine"]].append(((j,o), rec["start"], rec["end"]))
    for m, ops in m_ops.items():
        ops.sort(key=lambda x: x[1])
        for i in range(len(ops)-1):
            if ops[i][2] > ops[i+1][1]:
                print(f"  OVERLAP M{m}: {ops[i][0]} and {ops[i+1][0]}"); errors+=1

    if mc > max_mc: print(f"  MC BUDGET"); errors+=1
    if sh > max_shift: print(f"  SHIFT BUDGET"); errors+=1
    print(f"Validation: {'PASS' if errors==0 else f'{errors} ERRORS'}")

    if errors == 0:
        os.makedirs("/app/output", exist_ok=True)
        sl = sorted(sched.values(), key=lambda r: (r["start"],r["job"],r["op"]))
        sol = {"status":"REPAIRED","makespan":ms,"schedule":sl}
        with open("/app/output/solution.json","w") as f: json.dump(sol,f,indent=2)
        with open("/app/output/schedule.csv","w",newline="") as f:
            w = csv.DictWriter(f, fieldnames=["job","op","machine","start","end","dur"])
            w.writeheader()
            for r in sl: w.writerow(r)
        print(f"\nWrote output: makespan={ms}")
else:
    print("No feasible solution found!")
